\begin{theorem}[Koenigs linearisation]\label{cd2:koenigs}
If the multiplier satisfies $|\lambda|\notin\{0,1\}$, there is a map $\phi$, unique up to multiplication by a nonzero constant, such that the following diagram commutes.
\begin{figure}[H]\centering
\includegraphics[width=.32\textwidth]{cd2-fig-02.pdf}
\FigureTag{CD2.2}{fig:cd2-02}
\end{figure}
\end{theorem}
\begin{proof}
\emph{Case 1: $|\lambda|<1$.} Identify $f$ with its local coordinate expression $\widehat f$. Let $0$ be the fixed point. We have $f(z)=\lambda z+O(z^2)$ in $\mathbb D_{r_0}$ for some $r_0<1$, and
\[
|f(z)|\le|\lambda z|+C|z|^2\le(|\lambda|+C|z|)|z|\qquad(|z|<r_0).
\]
Choose $c$ with $|\lambda|<c<\sqrt{|\lambda|}$, and then choose $0<r\le r_0$ so that $|\lambda|+Cr\le c$. Then $|f(z)|\le c|z|$ for every $z\in\mathbb D_r$, so $f(z)\in\mathbb D_r$ and
$|f^{\circ n}(z)|\le c^n|z|<c^nr\to0$ as $n\to\infty$.
% Source page 4
This is precisely the push/pull we were discussing. There is $r<1$ such that $|f(z)|<c|z|$ on $\mathbb D_r$, with $c<1$. Let $\{z_n\}_n$ be the orbit of $z_0\in\mathbb D_r$. All these orbits converge to the origin, since $|z_n|\le rc^n$, and $|z_{n+1}-\lambda z_n|\le C|z_n|^2\le Cr^2c^{2n}$. Set $w_n=z_n/\lambda^n$. Then
\begin{align*}
|w_{n+1}-w_n|
&=\left|\frac{z_{n+1}}{\lambda^{n+1}}-\frac{z_n}{\lambda^n}\right|
=\frac{|z_{n+1}-\lambda z_n|}{|\lambda|^{n+1}}\\
&\le\frac{Cr^2c^{2n}}{|\lambda|^{n+1}}
=\frac{Cr^2}{|\lambda|}\left(\frac{c^2}{|\lambda|}\right)^n.
\end{align*}
The sequence $\{w_n\}_n$ is Cauchy, and its geometric bound is independent of $z_0$. The map $\phi_n(z_0)=f^{\circ n}(z_0)/\lambda^n$ is holomorphic on $\mathbb D_r$, with $\phi_n(f(z_0))=\lambda\phi_{n+1}(z_0)$. Taking $\phi=\lim_{n\to\infty}\phi_n$ gives $\phi\circ f=\lambda\phi$. Also, $\phi_n'(0)=1$, so $\phi'(0)=1$, and $\phi$ is a local conformal isomorphism around $0$.

\emph{Case 2: $|\lambda|>1$.} Since $f'(0)\ne0$, $f$ is locally invertible. Its local inverse has multiplier $0<|1/\lambda|<1$ at $0$.
% Source page 5
For uniqueness, if $\phi,\psi$ are two such Koenigs maps, then $\psi\circ\phi^{-1}$ commutes with $z\mapsto\lambda z$. If $\psi\circ\phi^{-1}(w)=\sum_{n\ge1}b_nw^n$, then $\lambda b_n=b_n\lambda^n$. Thus $b_k=0$ for every $k\ge2$, and $\psi=b_1\phi$.
\end{proof}
\subsection{Superattracting fixed points}
If $f'(0)=0$, then locally $f(z)=a_nz^n+a_{n+1}z^{n+1}+\cdots$. Thus $f$ has a zero of order $n$ at $0$, and in a suitable domain $f(z)=h(z)^nz^n$. Close to the origin in this domain, $f$ acts almost like the polynomial $a_nz^n$. The following theorem makes a much sharper claim.
\setcounter{theorem}{11}

\begin{theorem}[B\"ottcher]\label{cd2:bottcher}
If $0$ is a superattracting fixed point of $f$, with a zero of order $n$ at $0$, there is a map $\phi$, unique up to multiplication by an $(n-1)$th root of unity, such that the following diagram commutes.
\begin{figure}[H]\centering
\includegraphics[width=.32\textwidth]{cd2-fig-03.pdf}
\FigureTag{CD2.3}{fig:cd2-03}
\end{figure}
\end{theorem}
% Source page 6

\begin{theorem}\label{cd2:maximal}
There is a maximal $r$ such that $\psi\colon\mathbb D_r\to\mathcal A_0$ is a holomorphic inverse of the Koenigs coordinate $\phi$. The closed disc $\overline{\mathbb D_r}$ and $\psi(\overline{\mathbb D_r})$ are homeomorphic, and $\psi(\partial\mathbb D_r)$ contains a critical point of $f$.
\end{theorem}
% Source page 11

\begin{theorem}\label{cd2:maximal-bottcher}
There is a maximal $0<r\le1$ such that the B\"ottcher coordinate $\phi$ has a biholomorphic inverse on $\mathbb D_r$. If $r=1$, then $\mathbb D\cong\mathcal A_0$, and the superattracting point $\widehat p$ is the only critical point in $\mathcal A_0$. Otherwise there is another critical point in $\mathcal A_0$, on $\partial\psi(\mathbb D_r)$.
\end{theorem}
\begin{proof}
As before, a maximal $r\le1$ exists. For the following diagram to commute, the image of $\mathbb D_r$ under $z\mapsto z^n$, and all its subsequent iterates, must lie in $\mathbb D_r$, since $f^{\circ n}(\mathcal A_0)\subseteq\mathcal A_0$.
\begin{figure}[H]\centering
\includegraphics[width=.38\textwidth]{cd2-fig-09.pdf}
\FigureTag{CD2.9}{fig:cd2-09}
\end{figure}
Before, we had the luxury of the extended map $\phi$ on $\mathcal A$, so continuation of the holomorphic inverse by the identity theorem was a biholomorphic extension. We do not have that now, and must make do with the extension of $|\phi|$.

The map $\psi$ has no critical points in $\mathbb D_r$, since $\psi'(w)=0$ implies
$nw^{n-1}\psi'(w^n)=(f\circ\psi)'(w)=f'(\psi(w))\psi'(w)=0$.
Thus $w^n$, and all $w^{n^k}$, would be critical points, which is impossible by the identity theorem. Hence $\psi$ is locally injective (biholomorphic).

The set $\{(w_1,w_2)\in\mathbb D_r\times\mathbb D_r:\psi(w_1)=\psi(w_2)\}$ is closed. Thus choose $|w_1|=|w_2|$ minimal with $\psi(w_1)=\psi(w_2)$.
% Source page 14
Since $|\phi|$ extends to $\mathcal A$, we have $|\phi(\psi(w))|=|w|$ for all $w\in\mathbb D_\varepsilon$, the domain of biholomorphy. By the identity theorem, $|\phi(\psi(w))|=|w|$ for every $w\in\mathbb D_r$. Consequently, $\psi(w_1)=\psi(w_2)$ implies $|w_1|=|w_2|$.

Let $w_1'\in B_\varepsilon(w_1)$. The set $\psi^{-1}(\psi(B_\varepsilon(w_1)))$ contains $w_2$, so $\psi(B_\varepsilon(w_1))\cap\psi(B_\varepsilon(w_2))\ne\varnothing$. There are therefore $w_1',w_2'$ with $|w_1'|<|w_1|$ and $\psi(w_1')=\psi(w_2')$, a contradiction. Thus $\psi$ is injective, hence biholomorphic onto $\psi(\mathbb D_r)$.

If $r=1$ and $\psi(\mathbb D)\subsetneq\mathcal A_0$, take $z_0\in\partial U\cap\mathcal A_0$. Approximate $z_0$ by $\psi(w_j)$. Then $|\phi(\psi(w_j))|=|w_j|\to1$, so $|\phi(z_0)|=1$, and $z_0$ does not tend to $0$, contradicting $z_0\in\mathcal A_0$.

If $r<1$, just as before, a critical point on the boundary prevents extension of $\psi$ beyond its maximal disc $\mathbb D_r$.
\end{proof}
\begin{remark}
We defer the homeomorphism part to \BlogPost{parabolic-fixed-points-and-the-flower-theorem}{the next post}, where we explore topological properties, including continuous extension to $\partial\mathbb D_r$ of the inverses of B\"ottcher and Koenigs coordinates, and much more.
\end{remark}
\subsubsection{The number of attracting periodic points}
% Source page 15

\begin{theorem}\label{cd2:finite-attractors}
There are finitely many attracting periodic orbits.
\end{theorem}
\begin{proof}
For fixed points this follows because all immediate basins contain critical points, and a rational map has finitely many critical points. Given an attracting orbit $z_0\mapsto z_1\mapsto\cdots\mapsto z_0$ in $n$ steps, consider $f^{\circ n}$. The union of the immediate-basin components of the cycle contains a critical point of $f$, and distinct attracting cycles have disjoint immediate basins.
\end{proof}
\begin{proof}[Alternative proof]
Let $\widehat p\in O$ be an attracting fixed point, where $O$ is its immediate basin. If $O$ has no critical value of $f$, then there is a neighbourhood $U$ of $\widehat p$ and, for every $k\ge1$, a local inverse $g_k\colon U\to\widehat{\mathbb C}$ of $f^{\circ k}$. The family $\{g_k\}_k$ is normal, but $g_k'(\widehat p)$ is unbounded, since it is $\lambda^{-k}$ with $0<|\lambda|<1$.
\end{proof}
Critical points therefore bound the number of attracting periodic orbits. Let us try to extend this theorem to noncompact Riemann surfaces and nonrational maps.
\setcounter{definition}{8}\begin{definition}
For $f\colon S\to S'$, a \emph{critical value} is the image under $f$ of a critical point.
\end{definition}
\setcounter{definition}{9}\begin{definition}
If there is a curve $\gamma\colon[0,1)\to S$ that eventually leaves compact sets, but $\lim_{t\to1}f(\gamma(t))=v$, then $v$ is an \emph{asymptotic value}.
\end{definition}
% Source page 16

\begin{theorem}
Every proper holomorphic self-map $f\colon S\to S$ has a critical value in every immediate basin of an attracting orbit.
\end{theorem}

\begin{theorem}\label{cd3:asymptotic}
If an orbit $\{z_k\}_k$ of $z_0$ tends to $0$ and $z_k\ne0$ for every $k$, then $z_k\sim v_j/k^{1/n}$ as $k\to\infty$ for some attracting vector $v_j$. The analogous assertion holds for orbits converging to $0$ under $f^{-1}$.
\end{theorem}
% Source page 3

\begin{theorem}[Parabolic linearisation]\label{cd3:linearisation}
For any petal $P$, there is a conformal embedding $\alpha\colon P\to\mathbb C$, unique up to translation, making the following diagram commute. In the literature, $\alpha$ is called a \emph{Fatou coordinate}.
\begin{figure}[H]\centering
\includegraphics[width=.34\textwidth]{cd3-fig-07.pdf}
\FigureTag{CD3.7}{fig:cd3-07}
\end{figure}
\end{theorem}
Before proving the theorem, let us make a few observations. Recall that $\Re F_j(w)>\Re w+1/2$ and
$|F_j(w)-w-1|=O(1/\sqrt[n]{|w|})$.
\begin{observation}[1]
For $\widehat w\in\mathbb H_R$, the maps $\beta_k(w)=F_j^{\circ k}(w)-F_j^{\circ k}(\widehat w)$ converge locally uniformly to a biholomorphic map.
\end{observation}
% Source page 11

\begin{theorem}\label{cd5:components}
If $\mathcal A_0$ is an immediate basin of attraction, then $\widehat{\mathbb C}\setminus\mathcal A_0$ is either connected or has uncountably many components.
\end{theorem}
\begin{proof}
Choose $N_0$ small enough that $f(\overline{N_0})\subset N_0$ and $\partial N_0$ contains no forward image of a critical point. Such images are at most countable, because $\{z:f'(z)=0\}$ is finite. Let $\widehat z$ be the fixed point, and let $N_k$ be the component of $f^{-k}(N_0)$ containing $\widehat z$.

By invariance, $N_0\subset N_1\subset N_2\subset\cdots$. The iterates converge locally uniformly on compact sets. Given a path $P$ from $\widehat z$ to any $z\in\mathcal A_0$, we have $f^{\circ k}(P)\subseteq N_0$ for all sufficiently large $k$. Thus $z\in f^{-k}(N_0)$, and $\bigcup_kN_k=\mathcal A_0$.
% Source page 2
Therefore, $\widehat{\mathbb C}\setminus\mathcal A_0=\bigcap_k(\widehat{\mathbb C}\setminus N_k)$. If each $\partial N_k$ is connected, being a Jordan curve, and has no components, then $\{\widehat{\mathbb C}\setminus N_k\}_k$ is a nested sequence of compact connected sets. Hence $\widehat{\mathbb C}\setminus\mathcal A_0$ is connected.

Otherwise, $\overline{N_k}$ is a $d$-fold branched covering of $\overline{N_{k-1}}$, and the same holds for their components: if $C$ and $D$ are such components, $f|_C\colon C\to D$ is a $d$-fold branched covering. Thus
\[
f\colon\overline{N_k}\setminus f^{-1}(N_{k-1})\longrightarrow
\overline{N_{k-1}}\setminus N_{k-1}
\]
is also a $d$-fold branched covering. The following figure completes the proof. Since $f$ is conformal on $\partial N_k$, it sends the interior of $\partial N_k$ to the interior of $f(\partial N_k)$, preserving angles and therefore direction.
\begin{figure}[H]\centering
\includegraphics[width=.65\textwidth]{cd5-fig-01.pdf}
\FigureTag{CD5.1}{fig:cd5-01}
\end{figure}
The union of intersections of these Jordan-curve interiors forms $\widehat{\mathbb C}\setminus\mathcal A_0$, which is evidently uncountable.
\end{proof}
% Source page 3

\begin{theorem}\label{cd5:connectedness}
The sets $K$ and $\partial K$ are connected if and only if every critical point has a bounded orbit.
\end{theorem}
\begin{proof}
The polynomial has an attracting basin at infinity, denoted $\mathcal A(\infty)$. Critical points govern how far the B\"ottcher map can extend as a conformal isomorphism.
\begin{itemize}
\item If $\mathcal A\cong\mathbb D$, inversion of the sphere gives $\psi\colon\mathbb C\setminus\overline{\mathbb D}\to\mathbb C\setminus K$ conformally. Moreover,
\[
J=\partial K=\bigcap_{\varepsilon>0}\overline{\psi(A_{1+\varepsilon})}.
\]
Thus $J$ is connected, and hence $K$ is connected.
\item If $\mathcal A\cong\mathbb D_r$ with $r<1$, inversion gives $\mathbb C\setminus\overline{\mathbb D_r}\cong U\subset\mathbb C\setminus K$, now with $r>1$. The set $\mathcal A=\mathbb C\setminus K$ contains a critical point $c$ of $f$.
\end{itemize}
Set $v=f(c)$, and let $\phi$ denote the inverted B\"ottcher coordinate. Then $\phi(c)\in\partial\mathbb D_r$ and $\phi\circ f=z^d\circ\phi$, giving
\[
|\phi(v)|=|\phi(f(c))|=|\phi(c)^d|=r^d>r>1.
\]
% Source page 5
Consider the ray $R=\{t\phi(v):t\ge1\}$ in $\mathbb C\setminus\mathbb D_r$, and let $R'=\psi(R)$, where $\psi=\phi^{-1}$.
\begin{figure}[H]\centering
\includegraphics[width=.88\textwidth]{cd5-fig-02.pdf}
\FigureTag{CD5.2}{fig:cd5-02}
\end{figure}
The critical point $c$ splits the domain into two components. At $c$, the equation $f(z)=v$ has two solutions, at least locally, yielding two noncompact external rays $R_1',R_2'$.
\begin{figure}[H]\centering
\includegraphics[width=.72\textwidth]{cd5-fig-03.pdf}
\FigureTag{CD5.3}{fig:cd5-03}
\end{figure}
% Source page 6
The union $R_1'\cup R_2'$ cuts the plane into $V_0,V_1$. Since $f$ is open, $f(V_k)\supseteq\mathbb C\setminus R'\supset K$, giving $f(J\cap V_0)\supset J$. Thus $f(J_0)=J=f(J_1)$, where $J_0=J\cap V_0$ and $J_1=J\cap V_1$ are disjoint compact sets.

Repeat inductively:
\[
J_{10}=J_1\cap f^{-1}(J_0),\quad J_{00}=J_0\cap f^{-1}(J_0),\quad
J_{01}=J_0\cap f^{-1}(J_1),\quad J_{11}=J_1\cap f^{-1}(J_1).
\]
These are all nonempty disjoint compact sets. Continuing produces $J_{10100110\ldots}$ for every word $10100110\ldots\in\{0,1\}^{\mathbb N}$. Each such set is a component, so $J$ has uncountably many components. The same argument applies to $K$.
\end{proof}

\subsection*{Theorem 2.2 (Uniformization Theorem)} Any simply connected Riemann surface is conformally isomorphic to one of the following:
        \begin{enumerate}
            \item [(i)]The complex plane $\mathbb{C}$, consisting of complex numbers $z = x+iy$.
            \item [(ii)]The unit disk $\mathbb{D}$, consisting of complex numbers with norm $<1$.
            \item [(iii)]The Riemann sphere $\hat{\mathbb{C}}$, consisting of $\mathbb{C}$ together with $\infty$, wherein $w = 1/z$ is a coordinate map in a neighbourhood around $\infty$.
        \end{enumerate}

\subsection*{Lemma 2.5 (Completeness Lemma)} Let $S$ be a hyperbolic surface and let dist$_S$ denote the Poincar\'e distance on $S$. Then:
        \begin{enumerate}
            \item [(a)] $(S,$ dist$_S)$ is a complete metric space.
            \item [(b)] There exists a geodesic joining any two points of $S$.
        \end{enumerate}

\subsection*{Theorem 2.6 (Pick's Theorem)} Let $S$, $S'$ be hyperbolic and $f: S \rightarrow S'$ be holomorphic. Then:
        \begin{enumerate}
            \item $f$ is a conformal isomorphism, in particular an isometry.
            \item $f$ is a covering map, that is, a local isometry.
            \item $\forall$ compacts $K$, $f_{\big|K}$ is a contraction mapping.
        \end{enumerate}

\begin{theorem}[Connected and Cantor filled Julia sets]\label{thm:critical-connectedness}
Let $P$ be any polynomial, and let $K_P$ be its filled Julia set. Then:
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item $\Crit(P)\subset K_P$ if and only if $K_P$ is connected.
\setcounter{enumi}{1}\item If $\Crit(P)\cap K_P=\varnothing$, then $K_P$ is a Cantor set.
\end{enumerate}
\end{theorem}

\begin{corollary}[Connected Julia sets]
\[
\M=\{c\mid K(P_c)\text{ is connected}\}
    =\{c\mid J(P_c)\text{ is connected}\}.
\]
\end{corollary}

\begin{theorem}[Basic properties of the Mandelbrot set]\label{thm:basic-properties}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item $\M\subseteq\{c\mid |c|\le2\}$, $\M$ is compact and connected, and $\Chat\setminus\M$ is simply connected.
\setcounter{enumi}{1}\item $\M\cap\mathbb R=[-2,1/4]$.
\setcounter{enumi}{2}\item $|P_c^{\circ n}(0)|\le2$ for all $n\ge1$ if and only if $c\in\M$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Continuation of attracting cycles]\label{thm:attracting-continuation}
Let $a\in\Int(\M)$, and suppose $P_a$ has an attracting cycle of length $m$. Let $W$ be the component of $\Int(\M)$ containing $a$. Then, for every $c\in W$, $P_c$ has an attracting cycle $\{z_1(c),\ldots,z_m(c)\}$ of length $m$, and $c\mapsto z_i(c)$ is holomorphic for every $1\le i\le m$.
\end{theorem}

\begin{theorem}[Density of the interior]\label{thm:interior-dense}
$\Int(\M)$ is dense in $\M$.
\end{theorem}
\begin{proof}
Let $U$ be a disk that meets $\partial\M$, with $0\notin U$.
\begin{figure}[H]
\centering
\includegraphics[width=7.5cm,height=4.7cm,keepaspectratio]{qf-fig-01.pdf}
\FigureTag{QF1}{fig:qf-01}
\end{figure}
Suppose $U$ contains no parameter for which $0$ is periodic under $P_c$. Choose a branch of $\sqrt{-c}$ on $U$. Then
\[
P_c^{\circ n}(0)\ne0,\ \pm\sqrt{-c},
\]
since either of the latter two equalities would give $P_c^{\circ(n+1)}(0)=0$. Consequently,
\[
\left\{\frac{P_c^{\circ n}(0)}{\sqrt{-c}}\right\}_n
\]
omits $0,1,-1$ and is normal on $U$. Choose a convergent subsequence. On the nonempty open set $U\cap\Ext(\M)$ it tends to $\infty$, so its limit is identically $\infty$. But $U$ also contains a parameter of $\M$, at which the critical orbit, and hence this subsequence, is bounded. This contradiction proves that $U$ contains a parameter for which $0$ is periodic.
\end{proof}

\begin{corollary}[$J$-stability]
\[
\{c\mid P_c\text{ is }J\text{-stable}\}=\C\setminus\partial\M.
\]
\end{corollary}
\begin{proof}
By definition, if $c\in\Int(\M)$, the sequence $\{P_c^{\circ n}(0)\}_n$ is bounded and hence forms a normal family, so $c$ is $J$-stable. If $c\in\Ext(\M)$, then $P_c^{\circ n}(0)\to\infty$, again giving normality and $J$-stability. As in the preceding theorem, normality fails exactly on the boundary.
\end{proof}

\begin{theorem}[Invariant line fields]\label{thm:line-fields}
If $c\in\Int(\M)$, then the component of $\Int(\M)$ containing $c$ is non-hyperbolic if and only if $J(P_c)$ has positive measure and carries an invariant line field.
\end{theorem}
\begin{proof}
If $c$ belongs to a non-hyperbolic component, then $P_c$ has neither an attracting cycle nor an indifferent cycle, because indifferent points are persistently indifferent. A polynomial has no Herman ring, so by the Sullivan--Fatou classification, $J(P_c)$ is full.
\begin{figure}[H]
\centering
\begin{minipage}[c]{.26\linewidth}
\centering
\includegraphics[width=\linewidth,height=2cm,keepaspectratio]{qf-fig-02.pdf}
\FigureTag{QF2}{fig:qf-02}
\end{minipage}\hfill
\begin{minipage}[c]{.68\linewidth}
\centering
\includegraphics[width=\linewidth,height=4.8cm,keepaspectratio]{qf-fig-03.pdf}
\FigureTag{QF3}{fig:qf-03}
\end{minipage}
\end{figure}
The critical points of $P_\lambda$ are in $K(P_\lambda)$, so the B\"ottcher coordinate extends conformally. Hence $\phi_\lambda(z)$ is a holomorphic motion of $\C\setminus K(P_c)$.

% Source page 8
By the $\lambda$-lemma, $\phi_\lambda$ extends quasiconformally to $\overline\phi_\lambda\colon\Chat\to\Chat$.
\begin{figure}[H]
\centering
\includegraphics[width=12cm,height=5.1cm,keepaspectratio]{qf-fig-04.pdf}
\FigureTag{QF4}{fig:qf-04}
\end{figure}
If $J(P_c)$ has measure zero, then $P_c$ and $P_\lambda$ are conjugate by a M\"obius map. For $c\ne\lambda$, this is not possible.

Now suppose $J(P_c)$ has positive measure and supports an invariant line field $\mu$. Positive measure implies that $c\notin\Ext(\M)$, so $c\in\M$, as $P_c$ is not hyperbolic. Solve
\[
\frac{\partial_{\overline z}\phi_t}{\partial_z\phi_t}=t\mu
\]
to obtain a holomorphic family of quasiconformal maps $\phi_t\colon\C\to\C$, with $t\in\D$. Set $g_t=\phi_t\circ P_c\circ\phi_t^{-1}$, and normalize suitably to obtain $g_t(z)=z^2+c(t)$.

We prove that $c(t)$ is injective. If $c(t_1)=c(t_2)$ and $\phi_{t_1},\phi_{t_2}$ are conformal on $\C\setminus J(P_c)$, then, by continuity, $\phi_{t_1}=\phi_{t_2}$ on $J(P_c)$. Hence $t_1\mu=t_2\mu$. By the open mapping theorem, $\{c(t)\mid t\in\D\}$ is an open set in $\M$ containing $c$.
\end{proof}

\begin{theorem}[Quasicircle Julia sets]
If $c$ is in the principal hyperbolic component, then $J(P_c)$ is a quasicircle.
\end{theorem}
\begin{proof}
This is true for a much more general class of functions: if $R$ is a hyperbolic rational map with two Fatou components, then $J(R)$ is a quasicircle.

Let $D_1,D_2$ be the two Fatou components. Choose $\gamma_1$ so that $U_1$ has no critical points, and let $\gamma_2=R^{-1}(\gamma_1)$. One can choose $\gamma_1,\gamma_2$ to be analytic, since $D_1$ is a holomorphic image of the disk (the extension of the Koenigs coordinate is simply connected).
The restriction $R|_{\gamma_2}\colon\gamma_2\to\gamma_1$ is a $d$-fold covering map, where $d=\deg(R)$.

Pick a Riemann map $\widetilde R\colon U_1^c\to\Chat\setminus\overline{\D}_{\rho^d}$. This extends analytically (conformally, and quasisymmetrically) to $\psi_1\colon\partial U_1\to S^1_{\rho^d}$.
\begin{figure}[H]
\centering
\begin{minipage}[c]{.45\linewidth}
\centering
\includegraphics[width=\linewidth,height=6.4cm,keepaspectratio]{qf-fig-05.pdf}
\FigureTag{QF5}{fig:qf-05}
\end{minipage}\hfill
\begin{minipage}[c]{.49\linewidth}
\centering
\includegraphics[width=\linewidth,height=4.7cm,keepaspectratio]{qf-fig-06.pdf}
\FigureTag{QF6}{fig:qf-06}
\end{minipage}
\end{figure}
We have $\psi_1(R(z))=\psi_2(z)^d$. Fill $U_1\setminus U_2$ with a quasiconformal map, via the Ahlfors--Beurling extension:
\[
\psi\colon\overline{U_1\setminus U_2}\longrightarrow\overline{A}_{\rho,\rho^d}.
\]
Define
\[
g_1(z)=
\begin{cases}
R(z),&z\in U_2,\\
\widetilde R^{-1}(\psi(z)),&z\in U_1\setminus U_2,\\
\widetilde R^{-1}(\widetilde R(z)^d),&z\in D_1\setminus U_1.
\end{cases}
\]

% Source page 11
Using $g_1$, we can produce a $g_1$-invariant Beltrami form on $D_1$:
\[
\mu_1=
\begin{cases}
0,&U_1^c,\\
\psi^*(0),&U_1\setminus U_2,\\
(f^{\circ n})^*\mu,&\text{elsewhere }
\left(\displaystyle\bigcup_{n=1}^{\infty}g_1^{-n}(U_1\setminus U_2)\right).
\end{cases}
\]
Similarly, produce $\mu_2$ for $D_2$, and set
\[
\mu=\begin{cases}\mu_i&\text{on }D_i,\\0&\text{elsewhere},\end{cases}
\qquad
g=\begin{cases}g_i&\text{on }D_i,\\0&\text{elsewhere}.\end{cases}
\]
By the \BlogPostAt{the-mapping-theorem-and-invariant-complex-structures}{thm:measurable-riemann-mapping}{measurable Riemann mapping theorem}, there is a straightening map $\varphi$ such that $R_0:=\varphi\circ g\circ\varphi^{-1}$ is analytic. The map $R_0$ has critical fixed points of degree $d-1$ each at $0$ and $\infty$, since $g_1,g_2$ have the same. Thus $R_0\equiv z^d$, so $J(R)=\varphi(S^1)$, which is a quasicircle.
\end{proof}

\begin{theorem}[Uniformisation of $\C\setminus\M$]
Recall that, if $c\in\M^c$, then $A_c(\infty)$ is the only Fatou component, and the Julia set is totally disconnected.
\end{theorem}

\begin{theorem}[Sullivan's straightening theorem]
